(()=>{'use strict';
const canvas=document.querySelector('#world'),ctx=canvas.getContext('2d'),game=document.querySelector('#game');
const ui={healthFill:document.querySelector('#healthFill'),hungerFill:document.querySelector('#hungerFill'),thirstFill:document.querySelector('#thirstFill'),healthNum:document.querySelector('#healthNum'),hungerNum:document.querySelector('#hungerNum'),thirstNum:document.querySelector('#thirstNum'),inventory:document.querySelector('#inventory'),toast:document.querySelector('#toast'),interaction:document.querySelector('#interaction')};
const ITEMS={wood:{name:'Driftwood',icon:'🪵'},fiber:{name:'Palm fiber',icon:'🌿'},stone:{name:'Stone',icon:'🪨'},berry:{name:'Wild berries',icon:'🫐'},fish:{name:'Fish',icon:'🐟'},shell:{name:'Seashell',icon:'🐚'}};
const islands=[{name:'PALM ISLAND',seed:42,theme:'palm',npc:'Mara',intro:'Mara has been keeping watch on this beach. She smiles when she sees you.'},{name:'TIDELINE CAY',seed:81,theme:'cay',npc:'Pip',intro:'A curious little fox trots over, then decides you seem alright.'},{name:'GREENFALL KEY',seed:133,theme:'green',npc:'Jonah',intro:'Jonah, a stranded sailor, waves from the shade. Looks like you are not alone.'},{name:'SHELLBACK ISLE',seed:215,theme:'shell',npc:'Turtle',intro:'An old sea turtle rests beside a tide pool. You sit together a while.'}];
let state={x:0,y:0,health:100,hunger:88,thirst:83,day:1,time:0,bag:{wood:0,fiber:0,stone:0,berry:0,fish:0,shell:0},crafted:{shelter:false,raft:false,spear:false},island:0,found:new Set,met:new Set,animalsHunted:0,started:false,gameOver:false};let world={w:800,h:540,objects:[],water:[],island:{x:400,y:270,rx:316,ry:210},keys:{},last:0,toastTimer:null};
function rng(seed){return()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}}
function resize(){const r=game.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(r.width*d);canvas.height=Math.floor(r.height*d);canvas.style.width=r.width+'px';canvas.style.height=r.height+'px';ctx.setTransform(d,0,0,d,0,0);world.w=r.width;world.h=r.height;world.island={x:r.width*.5,y:r.height*.51,rx:Math.min(r.width*.405,420),ry:Math.min(r.height*.405,270)};generate();draw()}
function generate(){const island=islands[state.island],random=rng(island.seed);world.objects=[];const {x:cx,y:cy,rx,ry}=world.island;for(let i=0;i<130;i++){const a=random()*Math.PI*2,r=Math.sqrt(random()),x=cx+Math.cos(a)*rx*r,y=cy+Math.sin(a)*ry*r,dist=Math.sqrt(((x-cx)/rx)**2+((y-cy)/ry)**2);let type,amount=1;if(dist>.91){type='shell';}else if(dist>.78){type=random()<.55?'wood':'stone';}else{const roll=random();type=roll<.28?'wood':roll<.48?'fiber':roll<.67?'stone':roll<.82?'berry':'fish';if(type==='fish'&&dist>.72)type='berry';}if(type==='fish'&&dist>.55)type='shell';if(type==='wood'&&random()<.2)amount=2;world.objects.push({x,y,type,amount,scale:.7+random()*.6,phase:random()*6.28,alive:true});}world.objects.push({x:cx+rx*.2,y:cy-ry*.05,type:'camp',alive:true});if(state.island>0)world.objects.push({x:cx-rx*.23,y:cy+ry*.02,type:'person',name:island.npc,alive:true});else world.objects.push({x:cx-rx*.22,y:cy+ry*.15,type:'person',name:island.npc,alive:true});if(state.island===1||state.island===3)world.objects.push({x:cx+rx*.27,y:cy+ry*.2,type:'animal',alive:true,name:'fox'});if(state.island===2)world.objects.push({x:cx-rx*.32,y:cy-ry*.17,type:'animal',alive:true,name:'boar'});state.x=state.x||cx;state.y=state.y||cy+ry*.35;state.x=clamp(state.x,cx-rx*.73,cx+rx*.73);state.y=clamp(state.y,cy-ry*.72,cy+ry*.72);}
function clamp(v,a,b){return Math.max(a,Math.min(b,v))}function ellipse(x,y,rx,ry,color){ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()}
function draw(){const w=world.w,h=world.h;if(!w||!h)return;ctx.clearRect(0,0,w,h);const {x:cx,y:cy,rx,ry}=world.island;ctx.fillStyle='#25595a';ctx.fillRect(0,0,w,h);for(let y=0;y<h;y+=34){for(let x=0;x<w;x+=37){const n=Math.sin(x*.042+y*.027)*1.8;ellipse(x+n,y,1.3,1,'#ffffff0d')}}ellipse(cx,cy+ry*.08,rx*1.04,ry*1.065,'#183e40');ellipse(cx,cy+ry*.035,rx*1.012,ry*1.035,'#c7ae77');ellipse(cx,cy,rx,ry,'#9bb976');ellipse(cx,cy,rx*.93,ry*.92,'#a8c987');const island=islands[state.island];drawTerrain(cx,cy,rx,ry,island.theme);for(const o of world.objects)if(o.alive)drawObject(o);drawPlayer();if(state.crafted.shelter){ctx.fillStyle='#74563d';ctx.beginPath();ctx.moveTo(cx+rx*.43,cy-ry*.56);ctx.lineTo(cx+rx*.57,cy-ry*.56);ctx.lineTo(cx+rx*.5,cy-ry*.67);ctx.closePath();ctx.fill();ctx.fillStyle='#d2bc82';ctx.fillRect(cx+rx*.445,cy-ry*.56,rx*.11,ry*.06);ellipse(cx+rx*.5,cy-ry*.48,rx*.045,ry*.025,'#e99359');}if(state.crafted.raft){drawRaft(cx+rx*.61,cy-ry*.08)}drawDaylight()}
function drawTerrain(cx,cy,rx,ry,theme){const rnd=rng(islands[state.island].seed+987);for(let i=0;i<30;i++){const x=cx+(rnd()-.5)*rx*1.6,y=cy+(rnd()-.5)*ry*1.6;if(((x-cx)/rx)**2+((y-cy)/ry)**2>.83)continue;const s=4+rnd()*11;if(theme==='green'||theme==='palm'){if(rnd()<.6)drawPalm(x,y,s*(theme==='green'?1.2:1),rnd()*6.2);else ellipse(x,y,s*.7,s*.45,'#739b69')}else{ellipse(x,y,s*.65,s*.4,theme==='cay'?'#86ac79':'#93ad78');if(rnd()<.25)ellipse(x+s*.2,y-s*.12,s*.45,s*.25,'#d7c88d')}}for(let i=0;i<12;i++){const a=(i/12)*Math.PI*2,x=cx+Math.cos(a)*rx*.94,y=cy+Math.sin(a)*ry*.94;ellipse(x,y,2,2,'#efe0b0')}}
function drawPalm(x,y,s,r){ctx.save();ctx.translate(x,y);ctx.rotate(r*.1);ctx.strokeStyle='#725536';ctx.lineWidth=Math.max(2,s*.17);ctx.beginPath();ctx.moveTo(0,0);ctx.quadraticCurveTo(-s*.2,-s*.75,0,-s*1.4);ctx.stroke();const colors=['#4f7852','#638d57','#73985e'];for(let i=0;i<7;i++){const a=i/7*Math.PI*2;ctx.strokeStyle=colors[i%3];ctx.lineWidth=Math.max(1.5,s*.16);ctx.beginPath();ctx.moveTo(0,-s*1.25);ctx.quadraticCurveTo(Math.cos(a)*s*.6,-s*1.55+Math.sin(a)*s*.3,Math.cos(a)*s*1.35,-s*1.1+Math.sin(a)*s*.4);ctx.stroke()}ellipse(0,0,s*.14,s*.11,'#87633c');ctx.restore()}
function drawObject(o){const {x,y,scale:s=1,type}=o;ctx.save();ctx.translate(x,y);if(type==='wood'){ctx.rotate(-.27);ctx.fillStyle='#74543a';ctx.beginPath();ctx.roundRect(-10*s,-4*s,21*s,8*s,3);ctx.fill();ctx.fillStyle='#bd9360';ctx.beginPath();ctx.ellipse(10*s,0,3*s,4*s,0,0,Math.PI*2);ctx.fill()}else if(type==='fiber'){ellipse(0,1,5*s,2.4*s,'#63874d');ctx.strokeStyle='#55834f';ctx.lineWidth=2;for(let i=0;i<3;i++){ctx.beginPath();ctx.moveTo(-2*s,2*s);ctx.quadraticCurveTo((i-1)*3*s,-5*s,(i-1)*5*s,-7*s);ctx.stroke()}}else if(type==='stone'){ellipse(0,1,7*s,5*s,'#817e6e');ellipse(-2*s,-1,3*s,2*s,'#aaa796')}else if(type==='berry'){ellipse(0,2,5*s,4*s,'#638a55');ellipse(-2*s,-1,3.3*s,3.5*s,'#8f5c80');ellipse(3*s,0,3*s,3.4*s,'#b97190');ellipse(0,-2*s,2*s,2.7*s,'#6e466a')}else if(type==='fish'){ellipse(0,1,7*s,3.7*s,'#89aeb0');ctx.fillStyle='#89aeb0';ctx.beginPath();ctx.moveTo(6*s,1*s);ctx.lineTo(12*s,-3*s);ctx.lineTo(11*s,5*s);ctx.fill();ellipse(-3*s,-.5*s,1*s,1*s,'#283f3f')}else if(type==='shell'){ctx.fillStyle='#eee1b8';ctx.beginPath();ctx.moveTo(-5*s,3*s);ctx.quadraticCurveTo(-7*s,-6*s,0,-5*s);ctx.quadraticCurveTo(8*s,-5*s,5*s,3*s);ctx.closePath();ctx.fill();ctx.strokeStyle='#ceb88e';ctx.lineWidth=1;for(let i=-2;i<=2;i++){ctx.beginPath();ctx.moveTo(0,2*s);ctx.lineTo(i*2*s,-4*s);ctx.stroke()}}else if(type==='camp'){ellipse(0,3,17,8,'#766445');for(let i=0;i<5;i++){ctx.strokeStyle=i%2?'#654a32':'#886544';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-10+i*5,1);ctx.lineTo(7-i*4,7);ctx.stroke()}ellipse(-1,0,4,4,'#f19554');ellipse(-1,1,2,2,'#ffcb71')}else if(type==='person'){drawPerson(0,0,o.name)}else if(type==='animal'){drawAnimal(o.name)}ctx.restore()}
function drawPerson(x,y,name){ellipse(x,y+7,9,3,'#334c42aa');ellipse(x,y-2,6,8,'#d88759');ellipse(x,y-11,4.2,4.5,'#b97d58');ctx.fillStyle='#e7d2a3';ctx.beginPath();ctx.arc(x,y-12,5,Math.PI,0);ctx.lineTo(x+5,y-11);ctx.lineTo(x-5,y-11);ctx.fill();ctx.fillStyle='#263c38';ctx.fillRect(x-2,y-2,1.3,1);ctx.fillRect(x+1.5,y-2,1.3,1);ctx.font='9px DM Sans';ctx.textAlign='center';ctx.fillStyle='#243b36';ctx.fillText(name,x,y+20)}function drawAnimal(name){ellipse(0,5,12,5,'#3a4936');ellipse(0,0,9,5,name==='boar'?'#71624a':'#d18b53');ellipse(-7,-4,4,5,name==='boar'?'#71624a':'#d18b53');ellipse(3,-2,2,2,'#f4dfbb');ellipse(4,-2,1,1,'#263733');if(name==='boar'){ctx.fillStyle='#e9dfc2';ctx.beginPath();ctx.moveTo(7,1);ctx.lineTo(12,2);ctx.lineTo(8,4);ctx.fill()}}
function drawPlayer(){const bob=Math.sin(performance.now()/150)*1.4;ellipse(state.x,state.y+10,9,3,'#274a40aa');ellipse(state.x,state.y+bob,6,8,'#e8bc78');ellipse(state.x,state.y-9+bob,4.2,4.5,'#d89870');ctx.fillStyle='#e8e1c4';ctx.beginPath();ctx.arc(state.x,state.y-10+bob,5,Math.PI,0);ctx.lineTo(state.x+5,state.y-8+bob);ctx.lineTo(state.x-5,state.y-8+bob);ctx.fill();ctx.fillStyle='#29433e';ctx.fillRect(state.x-2,state.y+bob,1.3,1);ctx.fillRect(state.x+1.5,state.y+bob,1.3,1)}function drawRaft(x,y){ctx.save();ctx.translate(x,y);ctx.rotate(-.12);ctx.fillStyle='#775539';for(let i=-2;i<=2;i++){ctx.beginPath();ctx.roundRect(-15,i*4,30,3,1.5);ctx.fill()}ctx.strokeStyle='#dec184';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-10,-8);ctx.lineTo(10,8);ctx.moveTo(10,-8);ctx.lineTo(-10,8);ctx.stroke();ctx.restore()}
function drawDaylight(){const t=(state.time%1);ctx.fillStyle=`rgba(18,39,52,${.03+Math.max(0,Math.sin((t-.25)*Math.PI*2))*.08})`;ctx.fillRect(0,0,world.w,world.h)}
function nearest(){let best=null,dist=Infinity;for(const o of world.objects){if(!o.alive)continue;const d=Math.hypot(o.x-state.x,o.y-state.y);if(d<dist){best=o;dist=d}}return dist<40?best:null}
function move(dt){let dx=0,dy=0,k=world.keys;if(k.ArrowUp||k.w||k.W||k.up)dy--;if(k.ArrowDown||k.s||k.S||k.down)dy++;if(k.ArrowLeft||k.a||k.A||k.left)dx--;if(k.ArrowRight||k.d||k.D||k.right)dx++;if(dx||dy){const l=Math.hypot(dx,dy);dx/=l;dy/=l;const sp=135;state.x+=dx*sp*dt;state.y+=dy*sp*dt;const {x,y,rx,ry}=world.island,ox=(state.x-x)/rx,oy=(state.y-y)/ry;if(ox*ox+oy*oy>.73){state.x-=dx*sp*dt;state.y-=dy*sp*dt}}}
function gather(){const o=nearest();if(!o){notify('Nothing close by. Take a little wander.');return}if(o.type==='person'){if(!state.met.has(state.island)){state.met.add(state.island);notify(`${o.name}: "${islands[state.island].intro}"`);if(state.island===0){state.hunger=Math.min(100,state.hunger+7);state.bag.berry++;updateUI()}}else notify(`${o.name} waves. "Take care out there!"`);return}if(o.type==='animal'){if(state.bag.fish>0||state.crafted.spear){if(state.crafted.spear){state.bag.fish++;state.animalsHunted++;o.alive=false;notify('A clean catch. +1 fresh fish.')}else notify('You could hunt it with a spear, or leave it be.');}else notify('It darts away. Craft a spear if you plan to hunt.');updateUI();return}if(o.type==='camp'){if(state.crafted.shelter)notify('Your little shelter. Not bad for a castaway.');else notify('A good spot for a shelter. Gather 3 wood + 2 fiber to build one.');return}state.bag[o.type]=(state.bag[o.type]||0)+o.amount;o.alive=false;state.found.add(o.type);const nm=ITEMS[o.type].name;notify(`+${o.amount} ${nm.toLowerCase()}`);if(o.type==='berry')state.hunger=Math.min(100,state.hunger+5);if(o.type==='fish')state.hunger=Math.min(100,state.hunger+3);updateUI()}
function use(){if(state.bag.berry>0&&state.hunger<95){state.bag.berry--;state.hunger=Math.min(100,state.hunger+24);notify('Sweet and tart. Hunger restored.')}else if(state.bag.fish>0&&state.hunger<96){state.bag.fish--;state.hunger=Math.min(100,state.hunger+30);notify('A satisfying bite. Hunger restored.')}else if(state.thirst<85){state.thirst=Math.min(100,state.thirst+20);notify('You drink from the fresh-water spring.')}else notify('You feel alright for now.');updateUI()}
function recipeData(){return[{id:'shelter',name:'Palm-leaf shelter',desc:'A safe place to rest. Restores your strength.',cost:{wood:3,fiber:2},emoji:'🏕️'},{id:'raft',name:'Little raft',desc:'Sail away to discover another island.',cost:{wood:4,fiber:3},emoji:'⛵'},{id:'spear',name:'Hunting spear',desc:'Hunt wildlife for a hearty meal.',cost:{wood:2,stone:1},emoji:'🗡️'}]}
function has(cost){return Object.entries(cost).every(([k,n])=>state.bag[k]>=n)}function costText(cost){return Object.entries(cost).map(([k,n])=>`${n} ${ITEMS[k].name}`).join(' · ')}function craft(id){const r=recipeData().find(x=>x.id===id);if(!r||state.crafted[id]||!has(r.cost))return;for(const [k,n] of Object.entries(r.cost))state.bag[k]-=n;state.crafted[id]=true;notify(`${r.name} complete!`);renderRecipes();updateUI();draw()}
function showCraft(){document.querySelector('#craftModal').classList.add('open');renderRecipes()}function renderRecipes(){document.querySelector('#recipes').innerHTML=recipeData().map(r=>`<div class="recipe"><div><strong>${r.emoji} ${r.name}</strong><small>${state.crafted[r.id]?'Built already':costText(r.cost)}</small></div><button data-craft="${r.id}" ${state.crafted[r.id]||!has(r.cost)?'disabled':''}>${state.crafted[r.id]?'Done':'Build'}</button></div>`).join('')}
function sail(){if(!state.crafted.raft){notify('You need a raft first. Open Craft to build one.');return}state.island=(state.island+1)%islands.length;world.objects=[];state.x=state.y=0;generate();state.day++;notify(`You made landfall on ${islands[state.island].name.toLowerCase()}!`);updateUI();draw();if(state.met.size>=3&&state.island===3){setTimeout(()=>ending('The islands are home',`You found the others, built a shelter, and made it safely across the sea. Not bad for a washed-up castaway.`),1100)}}
