function notify(msg){ui.toast.textContent=msg;ui.toast.classList.add('show');clearTimeout(world.toastTimer);world.toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),2350)}function updateUI(){for(const [key,val] of [['health',state.health],['hunger',state.hunger],['thirst',state.thirst]]){ui[key+'Fill'].style.width=val+'%';ui[key+'Num'].textContent=Math.round(val)+'%';ui[key+'Fill'].style.background=val<26?'#e77b60':val<50?'#e7b961':'#c5dfad'}ui.inventory.innerHTML=Object.entries(state.bag).filter(([,n])=>n>0).map(([k,n])=>`<div class="inv-item"><span>${ITEMS[k].icon}</span>${n}</div>`).join('')||'<div class="inv-item">Empty pockets</div>';document.querySelector('#islandName').textContent=islands[state.island].name;document.querySelector('#dayLabel').textContent=`DAY ${state.day} · ${state.time<.35?'MORNING':state.time<.7?'AFTERNOON':'EVENING'}`;document.querySelector('#sailBtn').disabled=!state.crafted.raft;document.querySelector('#eatBtn').disabled=!(state.bag.berry||state.bag.fish)||state.hunger>94;document.querySelector('#drinkBtn').disabled=state.thirst>94;document.querySelector('#journalCount').textContent=Math.min(state.found.size,4);let q='A place to call home',t='Gather wood and fiber to make a small shelter. There is plenty to explore.',count=Math.min(state.bag.wood,3)+Math.min(state.bag.fiber,2),total=5;if(state.crafted.shelter&&!state.crafted.raft){q='A way across the water';t='Gather wood and fiber to build a raft. Who knows what you will find?';count=Math.min(state.bag.wood,4)+Math.min(state.bag.fiber,3);total=7}else if(state.crafted.raft){q='A wider world';t=`You have a raft. Visit ${Math.max(0,3-state.met.size)} more island${state.met.size===2?'':'s'} and meet the locals.`;count=state.met.size;total=3}else if(state.crafted.shelter){q='A way across the water';t='Gather wood and fiber to build a raft. Who knows what you will find?';count=Math.min(state.bag.wood,4)+Math.min(state.bag.fiber,3);total=7}document.querySelector('#questTitle').textContent=q;document.querySelector('#questText').textContent=t;document.querySelector('#questCount').textContent=`${count} / ${total}`;document.querySelector('#questFill').style.width=`${Math.min(100,count/total*100)}%`;}
function ending(title,text){document.querySelector('#endingTitle').textContent=title;document.querySelector('#endingText').textContent=text;document.querySelector('#ending').classList.add('show')}
function loop(ts){const dt=Math.min(.05,(ts-world.last)/1000||0);world.last=ts;if(state.started&&!state.gameOver){move(dt);state.time+=dt/150;state.hunger=Math.max(0,state.hunger-dt*.17);state.thirst=Math.max(0,state.thirst-dt*.24);if(state.hunger===0||state.thirst===0)state.health=Math.max(0,state.health-dt*1.4);if(state.health<=0){state.gameOver=true;ending('Washed ashore again','The islands will still be here. Take a breath, then give it another go.')}draw();const n=nearest();ui.interaction.classList.toggle('show',!!n);ui.interaction.innerHTML=n?`<span class="key">E</span>${n.type==='person'?`Talk to ${n.name}`:n.type==='animal'?'Hunt / observe':n.type==='camp'?'Inspect campsite':`Gather ${ITEMS[n.type].name}`}`:'';if(Math.floor(state.time*4)%4===0)updateUI()}requestAnimationFrame(loop)}
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();world.keys[e.key]=true;if(e.repeat)return;if(e.key.toLowerCase()==='e')gather();if(e.key===' ')use();if(e.key.toLowerCase()==='c')showCraft();if(e.key==='Escape')document.querySelector('#craftModal').classList.remove('open')});window.addEventListener('keyup',e=>world.keys[e.key]=false);document.querySelectorAll('.mobile-controls button').forEach(b=>{const on=e=>{e.preventDefault();world.keys[b.dataset.dir]=true};const off=e=>{e.preventDefault();world.keys[b.dataset.dir]=false};b.addEventListener('pointerdown',on);b.addEventListener('pointerup',off);b.addEventListener('pointerleave',off);b.addEventListener('pointercancel',off)});canvas.addEventListener('pointerdown',e=>{if(!state.started)return;const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;if(Math.hypot(x-state.x,y-state.y)<50){gather();return}world.keys.pointer=true;world.pointer={x,y};const moveTo=ev=>{const b=canvas.getBoundingClientRect();world.pointer={x:ev.clientX-b.left,y:ev.clientY-b.top}};canvas.setPointerCapture(e.pointerId);canvas.addEventListener('pointermove',moveTo);canvas.addEventListener('pointerup',()=>{world.keys.pointer=false;canvas.removeEventListener('pointermove',moveTo)},{once:true})});
// Pointer movement is an optional tap-to-walk helper for touch screens.
const rawMove=move;move=function(dt){if(world.keys.pointer&&world.pointer){const dx=world.pointer.x-state.x,dy=world.pointer.y-state.y,d=Math.hypot(dx,dy);if(d<8)world.keys.pointer=false;else{const speed=Math.min(135,d*2.7);const vx=dx/d*speed*dt,vy=dy/d*speed*dt;state.x+=vx;state.y+=vy;const {x,y,rx,ry}=world.island,ox=(state.x-x)/rx,oy=(state.y-y)/ry;if(ox*ox+oy*oy>.73){state.x-=vx;state.y-=vy}}}rawMove(dt)};
document.querySelector('#startBtn').onclick=()=>{state.started=true;document.querySelector('#intro').style.display='none';updateUI();notify('A little shelter first. Gather wood and palm fiber.');};document.querySelector('#craftBtn').onclick=showCraft;document.querySelector('#eatBtn').onclick=use;document.querySelector('#drinkBtn').onclick=()=>{if(state.thirst<96){state.thirst=Math.min(100,state.thirst+25);notify('You drink from the fresh-water spring.')}else notify('You are not thirsty right now.');updateUI()};document.querySelector('#sailBtn').onclick=sail;document.querySelector('#game').addEventListener('click',e=>{if(e.target.matches('[data-close]'))document.querySelector('#craftModal').classList.remove('open');if(e.target.matches('[data-craft]'))craft(e.target.dataset.craft)});document.querySelector('#continueBtn').onclick=()=>{document.querySelector('#ending').classList.remove('show');state.gameOver=false};document.querySelector('#soundBtn').onclick=e=>{e.currentTarget.textContent=e.currentTarget.textContent==='♪'?'♫':'♪';notify('A quiet breeze rustles the palms.')};window.addEventListener('resize',resize);resize();updateUI();requestAnimationFrame(loop);
